162	/**
163	 * One socket to Runlog, as a deck.
164	 *
165	 * It attaches signed in and names no run; the server pushes the held
166	 * list, the store picks, and this watches whichever it picked so the
167	 * doorbell rings here too. A ring is a fetch of the snapshot on the
168	 * signed-in route, which is where the offer is. A press names the run
169	 * and the offer's `seq`, so the page can refuse one the run has moved
170	 * past.
171	 */
172	export function openWire(account: Account, store: Store, deps: WireDeps = realDeps()): Wire {
173	  let socket: WebSocket | null = null;
174	  let wanted = false;
175	  let attempt = 0;
176	  let watching: string | null = null;
177	  const wsBase = account.apiBase.replace(/^http/, "ws");
178	
179	  const fetchSnapshot = async (run: string) => {
180	    const token = await deps.bearer(account);
181	    if (!token) return;
182	    try {
183	      const res = await deps.fetch(`${account.apiBase}/api/sessions/${encodeURIComponent(run)}/snapshot`, { headers: { authorization: `Bearer ${token}` } });
184	      if (res.ok) store.dispatch({ t: "snapshot", snapshot: (await res.json()) as never });
185	    } catch {
186	      /* the next ring tries again */
187	    }
188	  };
189	
190	  const follow = () => {
191	    const run = attachedRun(store.state);
192	    if (run === watching || !socket) return;
193	    watching = run;
194	    if (run) {
195	      socket.send(JSON.stringify({ t: "watch", id: run }));
196	      void fetchSnapshot(run);
197	    }
198	  };
199	  store.subscribe(follow);
200	
201	  const open = async () => {
202	    if (!wanted) return;
203	    const token = await deps.bearer(account);
204	    if (!token) {
205	      store.dispatch({ t: "session", state: "expired" });
206	      return;
207	    }
208	    store.dispatch({ t: "socket", state: "connecting" });
209	    const ws = new deps.WebSocket(`${wsBase}/ws?token=${encodeURIComponent(token)}&as=deck`);
210	    socket = ws;
211	    ws.onopen = () => {
212	      attempt = 0;
213	      watching = null;
214	      store.dispatch({ t: "socket", state: "open" });
215	    };
216	    ws.onmessage = (e) => {
217	      let m: Record<string, unknown>;
218	      try {
219	        m = JSON.parse(String(e.data)) as Record<string, unknown>;
220	      } catch {
221	        return;
222	      }
223	      if (m["t"] === "runs" && Array.isArray(m["runs"])) store.dispatch({ t: "runs", runs: m["runs"] as never, any: m["any"] === true });
224	      else if (m["t"] === "changed" && m["id"] === watching && watching) void fetchSnapshot(watching);
225	      else if (m["t"] === "drove" && typeof m["ref"] === "string")
226	        store.dispatch({ t: "drove", ref: m["ref"], ok: m["ok"] === true, ...(typeof m["say"] === "string" ? { say: m["say"] } : {}) });
227	    };
228	    ws.onclose = () => {
229	      socket = null;
230	      store.dispatch({ t: "socket", state: "closed" });
231	      if (wanted) setTimeout(() => void open(), backoffMs(attempt++, deps.random));
232	    };
233	  };
234	
235	  return {
236	    connect() {
237	      wanted = true;
238	      void open();
239	    },
240	    disconnect() {
241	      wanted = false;
242	      socket?.close();
243	    },
244	    press(p) {
245	      const run = attachedRun(store.state);
246	      const seq = store.state.snapshot?.offer?.seq;
247	      if (!run || seq === undefined || !socket) return null;
248	      const ref = `sd-${deps.now().toString(36)}-${Math.floor(deps.random() * 1e6).toString(36)}`;
249	      socket.send(JSON.stringify({ t: "drive", run, seq, ref, ...p }));
250	      return ref;
251	    },
252	  };
253	}
254	
255	function realDeps(): WireDeps {
256	  return { WebSocket: globalThis.WebSocket, fetch: (i, o) => fetch(i, o), bearer: realBearer, now: () => Date.now(), random: () => Math.random() };
257	}
