### Task 9: The socket client

**Files:**

- Create: `streamdeck/src/socket.ts`
- Create: `streamdeck/src/store.ts` (the live `DeckState` and its listeners)
- Test: `streamdeck/src/socket.test.ts`

**Interfaces:**

- Consumes: `reduce`, `DeckEvent`, `DeckState`, `attachedRun` from Task 6; `bearer` from Task 8; `GET /api/sessions/<id>/snapshot` from Task 2.
- Produces:

```ts
export interface Store { state: DeckState; dispatch(e: DeckEvent): void; subscribe(l: (s: DeckState) => void): () => void }
export function makeStore(): Store;
export interface Wire { connect(): void; disconnect(): void; press(p: { press: string; move?: string; answer?: Record<string, unknown> }): string | null }  // returns the ref, or null when nothing is attached
export function openWire(account: Account, store: Store, deps?: WireDeps): Wire;
export interface WireDeps { WebSocket: typeof WebSocket; fetch: typeof fetch; bearer: (a: Account) => Promise<string | null>; now: () => number; random: () => number }
```

- [ ] **Step 1: Write the failing test**

```ts
import { describe, expect, it, vi } from "vitest";
import { makeStore } from "./store.ts";
import { openWire } from "./socket.ts";

class FakeSocket {
  static last: FakeSocket;
  sent: string[] = [];
  onopen: (() => void) | null = null;
  onmessage: ((e: { data: string }) => void) | null = null;
  onclose: (() => void) | null = null;
  constructor(public url: string) { FakeSocket.last = this; }
  send(d: string) { this.sent.push(d); }
  close() { this.onclose?.(); }
}

const deps = (snapshot: unknown = { ready: true, offer: { seq: 1, primary: null, moves: [], undo: null, needsPage: null, presets: [] } }) => ({
  WebSocket: FakeSocket as never,
  fetch: vi.fn(async () => new Response(JSON.stringify(snapshot))) as never,
  bearer: async () => "tok",
  now: () => 1000,
  random: () => 0,
});

describe("the wire", () => {
  it("attaches as a deck and watches the run it is told is held", async () => {
    const store = makeStore();
    const wire = openWire({ apiBase: "https://api.test" }, store, deps());
    wire.connect();
    await new Promise((r) => setTimeout(r, 0));
    expect(FakeSocket.last.url).toBe("wss://api.test/ws?token=tok&as=deck");
    FakeSocket.last.onopen?.();
    FakeSocket.last.onmessage?.({ data: JSON.stringify({ t: "runs", runs: [{ id: "s1", name: "Thursday" }], any: true }) });
    expect(store.state.attached).toBe("s1");
    expect(FakeSocket.last.sent).toContain(JSON.stringify({ t: "watch", id: "s1" }));
  });

  it("fetches the snapshot when the run rings", async () => {
    const store = makeStore();
    const d = deps();
    const wire = openWire({ apiBase: "https://api.test" }, store, d);
    wire.connect();
    await new Promise((r) => setTimeout(r, 0));
    FakeSocket.last.onopen?.();
    FakeSocket.last.onmessage?.({ data: JSON.stringify({ t: "runs", runs: [{ id: "s1" }], any: true }) });
    FakeSocket.last.onmessage?.({ data: JSON.stringify({ t: "changed", id: "s1", seq: 7 }) });
    await new Promise((r) => setTimeout(r, 0));
    expect(d.fetch).toHaveBeenCalledWith("https://api.test/api/sessions/s1/snapshot", expect.objectContaining({ headers: { authorization: "Bearer tok" } }));
    expect(store.state.snapshot?.offer?.seq).toBe(1);
  });

  it("presses with the seq of the offer it can see", async () => {
    const store = makeStore();
    const wire = openWire({ apiBase: "https://api.test" }, store, deps());
    wire.connect();
    await new Promise((r) => setTimeout(r, 0));
    FakeSocket.last.onopen?.();
    FakeSocket.last.onmessage?.({ data: JSON.stringify({ t: "runs", runs: [{ id: "s1" }], any: true }) });
    FakeSocket.last.onmessage?.({ data: JSON.stringify({ t: "changed", id: "s1", seq: 7 }) });
    await new Promise((r) => setTimeout(r, 0));
    const ref = wire.press({ press: "primary" });
    expect(ref).toMatch(/^sd-/);
    expect(JSON.parse(FakeSocket.last.sent.at(-1)!)).toEqual({ t: "drive", run: "s1", seq: 1, ref, press: "primary" });
  });

  it("goes back to Sign in again when the bearer is refused", async () => {
    const store = makeStore();
    const wire = openWire({ apiBase: "https://api.test" }, store, { ...deps(), bearer: async () => null });
    wire.connect();
    await new Promise((r) => setTimeout(r, 0));
    expect(store.state.session).toBe("expired");
  });
});
```

