5	class FakeSocket {
6	  static last: FakeSocket;
7	  sent: string[] = [];
8	  onopen: (() => void) | null = null;
9	  onmessage: ((e: { data: string }) => void) | null = null;
10	  onclose: (() => void) | null = null;
11	  constructor(public url: string) {
12	    FakeSocket.last = this;
13	  }
14	  send(d: string) {
15	    this.sent.push(d);
16	  }
17	  close() {
18	    this.onclose?.();
19	  }
20	}
21	
22	const deps = (
23	  snapshot: unknown = { ready: true, offer: { seq: 1, primary: null, moves: [], undo: null, needsPage: null, presets: [] } },
24	) => ({
25	  WebSocket: FakeSocket as never,
26	  fetch: vi.fn(async () => new Response(JSON.stringify(snapshot))) as never,
27	  bearer: async () => "tok",
