1	import type { Account } from "./session.ts";
2	import { bearer as realBearer } from "./session.ts";
3	import type { Store } from "./store.ts";
4	import { attachedRun } from "./state.ts";
5	
6	export interface WireDeps {
7	  WebSocket: typeof WebSocket;
8	  fetch: typeof fetch;
9	  bearer: (a: Account) => Promise<string | null>;
10	  now: () => number;
11	  random: () => number;
12	}
13	
14	export interface Wire {
15	  connect(): void;
16	  disconnect(): void;
17	  press(p: { press: string; move?: string; answer?: Record<string, unknown> }): string | null;
18	}
19	
20	/** The app's own rule: a second, doubling, capped at half a minute, with a little jitter. */
21	function backoffMs(attempt: number, random: () => number): number {
22	  return Math.min(30_000, 1000 * 2 ** attempt) * (0.8 + random() * 0.4);
23	}
24	
25	/**
26	 * One socket to Runlog, as a deck.
27	 *
28	 * It attaches signed in and names no run; the server pushes the held
29	 * list, the store picks, and this watches whichever it picked so the
30	 * doorbell rings here too. A ring is a fetch of the snapshot on the
31	 * signed-in route, which is where the offer is. A press names the run
32	 * and the offer's `seq`, so the page can refuse one the run has moved
33	 * past.
34	 */
35	export function openWire(account: Account, store: Store, deps: WireDeps = realDeps()): Wire {
36	  let socket: WebSocket | null = null;
37	  let wanted = false;
38	  let attempt = 0;
39	  let watching: string | null = null;
40	  const wsBase = account.apiBase.replace(/^http/, "ws");
41	
42	  const fetchSnapshot = async (run: string) => {
43	    const token = await deps.bearer(account);
44	    if (!token) return;
45	    try {
46	      const res = await deps.fetch(`${account.apiBase}/api/sessions/${encodeURIComponent(run)}/snapshot`, {
47	        headers: { authorization: `Bearer ${token}` },
48	      });
49	      if (res.ok) store.dispatch({ t: "snapshot", snapshot: (await res.json()) as never });
50	    } catch {
51	      /* the next ring tries again */
52	    }
53	  };
54	
55	  const follow = () => {
56	    const run = attachedRun(store.state);
57	    if (run === watching || !socket) return;
58	    watching = run;
59	    if (run) {
60	      socket.send(JSON.stringify({ t: "watch", id: run }));
61	      void fetchSnapshot(run);
62	    }
63	  };
64	  store.subscribe(follow);
65	
66	  const open = async () => {
67	    if (!wanted) return;
68	    const token = await deps.bearer(account);
69	    if (!token) {
70	      store.dispatch({ t: "session", state: "expired" });
71	      return;
72	    }
73	    store.dispatch({ t: "socket", state: "connecting" });
74	    const ws = new deps.WebSocket(`${wsBase}/ws?token=${encodeURIComponent(token)}&as=deck`);
75	    socket = ws;
76	    ws.onopen = () => {
77	      attempt = 0;
78	      watching = null;
79	      store.dispatch({ t: "socket", state: "open" });
80	      ws.send(JSON.stringify({ t: "hello" }));
81	    };
82	    ws.onmessage = (e) => {
83	      let m: Record<string, unknown>;
84	      try {
85	        m = JSON.parse(String(e.data)) as Record<string, unknown>;
86	      } catch {
87	        return;
88	      }
89	      if (m["t"] === "runs" && Array.isArray(m["runs"])) store.dispatch({ t: "runs", runs: m["runs"] as never, any: m["any"] === true });
90	      else if (m["t"] === "changed" && m["id"] === watching && watching) void fetchSnapshot(watching);
91	      else if (m["t"] === "drove" && typeof m["ref"] === "string")
92	        store.dispatch({
93	          t: "drove",
94	          ref: m["ref"],
95	          ok: m["ok"] === true,
96	          ...(typeof m["say"] === "string" ? { say: m["say"] } : {}),
97	          ...(typeof m["seq"] === "number" ? { seq: m["seq"] } : {}),
98	        });
99	    };
100	    ws.onclose = () => {
101	      socket = null;
102	      store.dispatch({ t: "socket", state: "closed" });
103	      if (wanted) setTimeout(() => void open(), backoffMs(attempt++, deps.random));
104	    };
105	  };
106	
107	  return {
108	    connect() {
109	      wanted = true;
110	      void open();
111	    },
112	    disconnect() {
113	      wanted = false;
114	      socket?.close();
115	    },
116	    press(p) {
117	      const run = attachedRun(store.state);
118	      const seq = store.state.snapshot?.offer?.seq;
119	      if (!run || seq === undefined || !socket) return null;
120	      const ref = `sd-${deps.now().toString(36)}-${Math.floor(deps.random() * 1e6).toString(36)}`;
121	      socket.send(JSON.stringify({ t: "drive", run, seq, ref, ...p }));
122	      return ref;
123	    },
124	  };
125	}
126	
127	function realDeps(): WireDeps {
128	  return {
129	    WebSocket: globalThis.WebSocket,
130	    fetch: (i, o) => fetch(i, o),
131	    bearer: realBearer,
132	    now: () => Date.now(),
133	    random: () => Math.random(),
134	  };
135	}

